                .andExpect(jsonPath("$.itinerary", hasSize(2)));

        load("LEG1", 1, List.of("BAG1", "BAG2")).andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2))
                .andExpect(jsonPath("$.loaded", contains("BAG1", "BAG2")));

