        // 引用不存在的航段
        registerBag("BAG_X", List.of("LEG_A", "LEG_MISSING")).andExpect(status().isUnprocessableEntity());
        // 航段数超出 1~5（参数校验 400）
        registerBag("BAG_X", List.of()).andExpect(status().isBadRequest());
