public PassengerListResponse getPassengers(String legId) {
    LegRow leg = findLeg(legId);
    if (leg == null) throw ApiException.notFound("航段不存在: " + legId);
    List<String> passengers = boardedPassengers(legId);
    List<String> sealedPassengers = leg.sealedPassengers() == null ? null : readJsonList(leg.sealedPassengers());
    Map<String, List<String>> sealedBags = leg.sealedPassengerBags() == null ? null : readJsonMap(leg.sealedPassengerBags());
    return new PassengerListResponse(leg.legId(), leg.status(), leg.version(), passengers,
